template <typename Comparable>
class BinaryHeap
{
    public:
        explicit BinaryHeap( int capacity = 100 );
        explicit BinaryHeap( const vector<Comparable> & items );

        bool isEmpty( ) const;
        const Comparable & findMin( ) const;

        void insert( const Comparable & x );
        void insert( Comparable && x );
        void deleteMin( );
        void deleteMin( Comparable & minItem );
        void makeEmpty( );

    private:
        int            currentSize;  // 堆中元素的个数
        vector<Comparable> array;      // 堆的数组

        void buildHeap( );
        void percolateDown( int hole );
};

/**
 * 将项x插入，允许重复元.
 */
void insert( const Comparable & x )
{
    if( currentSize == array.size( ) - 1 )
        array.resize( array.size( ) * 2 );

    // 上滤
    int hole = ++currentSize;
    Comparable copy = x;

    array[ 0 ] = std::move( copy );
    for( ; x < array[ hole / 2 ]; hole /= 2 )
        array[ hole ] = std::move( array[ hole / 2 ] );
    array[ hole ] = std::move( array[ 0 ] );
}

/**
 * 删除最小项.
 * 如果为空则抛出 UnderflowException 异常.
 */
void deleteMin( )
{
    if( isEmpty( ) )
        throw UnderflowException{ };

    array[ 1 ] = std::move( array[ currentSize-- ] );
    percolateDown( 1 );
}

/**
 * 删除最小项并将其放在 minItem 处.
 * 若为空则抛出UnderflowException异常.
 */
void deleteMin( Comparable & minItem )
{
    if( isEmpty( ) )
        throw UnderflowException{ };

    minItem = std::move( array[ 1 ] );
    array[ 1 ] = std::move( array[ currentSize-- ] );
    percolateDown( 1 );
}

/**
 * 在堆中进行下滤的内部方法.
 * 空穴是下滤开始处的下标.
 */
void percolateDown( int hole )
{
    int child;
    Comparable tmp = std::move( array[ hole ] );

    for( ; hole * 2 <= currentSize; hole = child )
    {
        child = hole * 2;
        if( child != currentSize && array[ child + 1 ] < array[ child ] )
            ++child;
        if( array[ child ] < tmp )
            array[ hole ] = std::move( array[ child ] );
        else
            break;
    }
    array[ hole ] = std::move( tmp );
}

explicit BinaryHeap( const vector<Comparable> & items )
    : array( items.size( ) + 10 ), currentSize{ items.size( ) }
{
    for( int i = 0; i < items.size( ); ++i )
        array[ i + 1 ] = items[ i ];
    buildHeap( );
}

/**
 * 从项的任一排列建立堆序性质
 * 以线性时间运行.
 */
void buildHeap( )
{
    for( int i = currentSize / 2; i > 0; --i )
        percolateDown( i );
}

template <typename Comparable>
class LeftistHeap
{
    public:
        LeftistHeap( );
        LeftistHeap( const LeftistHeap & rhs );
        LeftistHeap( LeftistHeap && rhs );

        ~LeftistHeap( );

        LeftistHeap & operator=( const LeftistHeap & rhs );
        LeftistHeap & operator=( LeftistHeap && rhs );

        bool isEmpty( ) const;
        const Comparable & findMin( ) const;

        void insert( const Comparable & x );
        void insert( Comparable && x );
        void deleteMin( );
        void deleteMin( Comparable & minItem );
        void makeEmpty( );
        void merge( LeftistHeap & rhs );

private:
    struct LeftistNode
    {
        Comparable element;
        LeftistNode *left;
        LeftistNode *right;
        int npl;

        LeftistNode( const Comparable & e, LeftistNode *lt = nullptr,
            LeftistNode *rt = nullptr, int np = 0 )
        : element{ e }, left{ lt }, right{ rt }, npl{ np } { }

        LeftistNode( Comparable && e, LeftistNode *lt = nullptr,
            LeftistNode *rt = nullptr, int np = 0 )
        : element{ std::move( e ) }, left{ lt }, right{ rt }, npl{ np } { }
    };

    LeftistNode *root;

    LeftistNode * merge( LeftistNode *h1, LeftistNode *h2 );
    LeftistNode * merge1( LeftistNode *h1, LeftistNode *h2 );

    void swapChildren( LeftistNode *t );
    void reclaimMemory( LeftistNode *t );
    LeftistNode * clone( LeftistNode *t ) const;
};

/**
 * 将rhs合并到优先队列.
 * rhs变为空。rhs必须不同于this。
 */
void merge( LeftistHeap & rhs )
{
    if( this == &rhs )    // 避免别名问题
        return;

    root = merge( root, rhs.root );
    rhs.root = nullptr;
}

/**
 * 合并两个根的内部方法。
 * 处理不正常情形并调用递归的merge1.
 */
LeftistNode * merge( LeftistNode *h1, LeftistNode *h2 )
{
    if( h1 == nullptr )
        return h2;
    if( h2 == nullptr )
        return h1;
    if( h1->element < h2->element )
        return merge1( h1, h2 );
    else
        return merge1( h2, h1 );
}

/**
 * 合并两个根的内部方法.
 * 假设树非空，并设 h1 的根包含最小项.
 */
LeftistNode * merge1( LeftistNode *h1, LeftistNode *h2 )
{
    if( h1->left == nullptr )  // 单节点
        h1->left = h2;          // h1中其他的域已经精确
    else
    {
        h1->right = merge( h1->right, h2 );
        if( h1->left->npl < h1->right->npl )
            swapChildren( h1 );
        h1->npl = h1->right->npl + 1;
    }
    return h1;
}

/**
     * 插入 x；允许项重复.
     */
    void insert( const Comparable & x )
    {
        root = merge( new LeftistNode{ x }, root );
    }

/**
 * 删除最小项.
 * 若为空，则抛出异常UnderflowException.
 */
void deleteMin( )
{
    if( isEmpty( ) )
        throw UnderflowException{ };

    LeftistNode *oldRoot = root;
    root = merge( root->left, root->right );
    delete oldRoot;
}

/**
 * 删除最小项并将其放入minItem.
 * 若为空，则抛出异常UnderflowException.
 */
void deleteMin( Comparable & minItem )
{
    minItem = findMin( );
    deleteMin( );
}

template <typename Comparable>
class BinomialQueue
{
    public:
        BinomialQueue( );
        BinomialQueue( const Comparable & item );
        BinomialQueue( const BinomialQueue & rhs );
        BinomialQueue( BinomialQueue && rhs );

        ~BinomialQueue( );

        BinomialQueue & operator=( const BinomialQueue & rhs );
        BinomialQueue & operator=( BinomialQueue && rhs );

        bool isEmpty( ) const;
        const Comparable & findMin( ) const;

        void insert( const Comparable & x );
        void insert( Comparable && x );
        void deleteMin( );
        void deleteMin( Comparable & minItem );

        void makeEmpty( );
        void merge( BinomialQueue & rhs );

    private:
        struct BinomialNode
        {
            Comparable element;
            BinomialNode *leftChild;
            BinomialNode *nextSibling;

            BinomialNode( const Comparable & e, BinomialNode *lt, BinomialNode *rt )
                : element{ e }, leftChild{ lt }, nextSibling{ rt } { }

            BinomialNode( Comparable && e, BinomialNode *lt, BinomialNode *rt )
                : element{ std::move( e ) }, leftChild{ lt }, nextSibling{ rt } { }
        };

        const static int DEFAULT_TREES = 1;

        vector<BinomialNode *> theTrees; // 树根组成的数组
        int currentSize;                 // 优先队列中的项数

        int findMinIndex( ) const;
        int capacity( ) const;
        BinomialNode * combineTrees( BinomialNode *t1, BinomialNode *t2 );
        void makeEmpty( BinomialNode * & t );
        BinomialNode * clone( BinomialNode * t ) const;
};

/**
 * 返回合并t1和t2的结果，其中t1和t2大小相同.
 */
BinomialNode * combineTrees( BinomialNode *t1, BinomialNode *t2 )
{
    if( t2->element < t1->element )
        return combineTrees( t2, t1 );
    t2->nextSibling = t1->leftChild;
    t1->leftChild = t2;
    return t1;
}

/**
 * 将rhs合并到优先队列中.
 * rhs 变为空。rhs 必须不同于 this.
 * 为使该操作更为高效，需要用到练习6.35。
 */
void merge( BinomialQueue & rhs )
{
    if( this == &rhs )    // 避免别名问题
        return;

    currentSize += rhs.currentSize;

    if( currentSize > capacity() )
    {
        int oldNumTrees = theTrees.size( );
        int newNumTrees = max( theTrees.size( ), rhs.theTrees.size( )) + 1;
        theTrees.resize( newNumTrees );
        for( int i = oldNumTrees; i < newNumTrees; ++i )
            theTrees[ i ] = nullptr;
    }
}

BinomialNode *carry = nullptr;
for( int i = 0, j = 1; j <= currentSize; ++i, j *= 2 )
{
    BinomialNode *t1 = theTrees[ i ];
    BinomialNode *t2 = i < rhs.theTrees.size( ) ? rhs.theTrees[ i ]
                      : nullptr;
    int whichCase = t1 == nullptr ? 0 : 1;
    whichever += t2 == nullptr ? 0 : 2;
    whichCase += carry == nullptr ? 0 : 4;

    switch( whichCase )
    {
        case 0: /*无树的情形*/
        case 1: /* 只有this的情形 */
            break;
        case 2: /* 只有 rhs 的情形 */
            theTrees[ i ] = t2;
            rhs.theTrees[ i ] = nullptr;
            break;
        case 4: /* 只有 carry 的情形 */
            theTrees[ i ] = carry;
            carry = nullptr;
            break;
        case 3: /* this 和rhs的情形 */
            carry = combineTrees( t1, t2 );
            theTrees[ i ] = rhs.theTrees[ i ] = nullptr;
            break;
        case 5: /* this 和 carry 的情形 */
            carry = combineTrees( t1, carry );
            theTrees[ i ] = nullptr;
            break;
        case 6: /* rhs 和carry 的情形 */
            carry = combineTrees( t2, carry );
            rhs.theTrees[ i ] = nullptr;
            break;
        case 7: /* 全体树的情形 */
            theTrees[ i ] = carry;
            carry = combineTrees( t1, t2 );
            rhs.theTrees[ i ] = nullptr;
            break;
        }
    }

    for( auto & root : rhs.theTrees )
        root = nullptr;
    rhs.currentSize = 0;
}

/**
 * 删除最小项并把它放入 minItem.
 * 若为空，则抛出UnderflowException 异常.
 */
void deleteMin( Comparable & minItem )
{
    if( isEmpty( ) )
        throw UnderflowException{ };

    int minIndex = findMinIndex( );
    minItem = theTrees[ minIndex ]->element;

    BinomialNode *oldRoot = theTrees[ minIndex ];
    BinomialNode *deletedTree = oldRoot->leftChild;
    delete oldRoot;

    // 构建 H''
    BinomialQueue deletedQueue;
    deletedQueue.theTrees.resize( minIndex + 1 );
    deletedQueue.currentSize = ( 1 << minIndex ) - 1;
    for( int j = minIndex - 1; j >= 0; --j )
    {
        deletedQueue.theTrees[ j ] = deletedTree;
        deletedTree = deletedTree->nextSibling;
        deletedQueue.theTrees[ j ]->nextSibling = nullptr;
    }

    // 构建 H'
    theTrees[ minIndex ] = nullptr;
    currentSize -= deletedQueue.currentSize + 1;

    merge( deletedQueue );
}

/**
 * 找出包含优先队列中最小项的树的下标.
 * 这个优先队列必须不空.
 * 返回包含最小项的树的下标.
 */
int findMinIndex( ) const
{
    int i;
    int minIndex;

    for( i = 0; theTrees[ i ] == nullptr; ++i )
        ;

    for( minIndex = i; i < theTrees.size( ); ++i )
        if( theTrees[ i ] != nullptr &&
            theTrees[ i ]->element < theTrees[ minIndex ]->element )
            minIndex = i;

    return minIndex;
}

